import{_ as s,o as n,c as o,af as a}from"./chunks/framework.B28LkSoM.js";const u=JSON.parse('{"title":"Linux概述与系统安装","description":"第 19 章从\\"服务器上跑的到底是什么系统\\"讲起——Linux 是什么、操作系统按场景怎么分类、内核版和发行版差在哪；然后在 VMware 里装一台 CentOS 7、配好 NAT 网络查到 IP、用 FinalShell 远程连上去，最后把 Linux 的目录结构和绝对相对路径认清","frontmatter":{"title":"Linux概述与系统安装","published":"2026-09-29T00:00:00.000Z","description":"第 19 章从\\"服务器上跑的到底是什么系统\\"讲起——Linux 是什么、操作系统按场景怎么分类、内核版和发行版差在哪；然后在 VMware 里装一台 CentOS 7、配好 NAT 网络查到 IP、用 FinalShell 远程连上去，最后把 Linux 的目录结构和绝对相对路径认清","tags":["JavaWeb","Linux","部署"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-106-linux-intro-install.webp","order":106,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/106-Linux概述与系统安装.md","filePath":"posts/学习文档/JavaWeb学习笔记/106-Linux概述与系统安装.md"}'),e={name:"posts/学习文档/JavaWeb学习笔记/106-Linux概述与系统安装.md"};function d(r,t,i,c,l,p){return n(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790640000000"},[...t[0]||(t[0]=[a(`<p><a href="/posts/编程学习/javaweb学习笔记/105-前端打包部署/">105 篇</a>把前端工程打包成 <code>dist</code>、交给 nginx 从 80 端口发出去——但那台 nginx 还在<strong>自己的 Windows 电脑</strong>上。真正上线时，这一堆东西（前端静态文件、后端 jar、MySQL、Redis）要放到<strong>机房里的一台服务器</strong>上，而服务器上跑的操作系统，绝大多数是 <strong>Linux</strong>。</p><p>这一篇是第 19 章（项目部署）的开头，覆盖 <strong>PPT 第 1～21 页</strong>：先讲清 Linux 是什么、为什么后端必须会它，再手把手走一遍<strong>装一台 CentOS 7 虚拟机 → 配网络 → 查到 IP → 远程连上去 → 认清目录结构</strong>。</p><table tabindex="0"><thead><tr><th>PPT 页</th><th>内容</th><th>本篇对应小节</th></tr></thead><tbody><tr><td>1～3</td><td>封面、课程全景图（Web 前端基础 / Web 前端实战 / Web 后端基础 / Web 后端实战 / <strong>Web 项目部署</strong>）、章节标题&quot;项目部署(Linux)&quot;</td><td>从打包完成到&quot;真上线&quot;</td></tr><tr><td>4</td><td>Linux 是什么 + 操作系统分类表 + 后端为什么要学 Linux（软件环境 / 项目部署）</td><td>操作系统分类与&quot;为什么后端要学 Linux&quot;</td></tr><tr><td>5</td><td>本章目录页（Linux 概述 / Linux 常用命令 / Linux 软件安装 / 项目部署）</td><td>从打包完成到&quot;真上线&quot;</td></tr><tr><td>6</td><td>小节页——Linux 概述 01（系统安装 / 远程连接 / 目录介绍）</td><td>本节导读</td></tr><tr><td>7</td><td>Linux 系统版本：内核版 vs 发行版 + 6 个常见发行版</td><td>内核版与发行版</td></tr><tr><td>8</td><td>安装方式：物理机安装 / 虚拟机安装 + 三款虚拟机软件</td><td>物理机与虚拟机</td></tr><tr><td>9</td><td>VMware 安装（双击安装程序）</td><td>装 VMware</td></tr><tr><td>10</td><td>虚拟机网络配置（NAT 模式）</td><td>网络配置</td></tr><tr><td>11</td><td>挂载镜像（解压 CentOS7 镜像包、双击 .vmx、启动服务器 root/1234）</td><td>挂载镜像与开机</td></tr><tr><td>12</td><td>虚拟网络编辑器 → NAT → 子网 IP 192.168.100.0、<code>ip addr</code>、start-ens33.sh、init 0/6</td><td>网络配置</td></tr><tr><td>13</td><td>远程连接的由来（公司在北京，服务器可能在上海/天津/香港/海外）</td><td>远程连接</td></tr><tr><td>14</td><td>小节页——重复第 6 页</td><td>远程连接</td></tr><tr><td>15</td><td>远程连接工具（SSH 协议；Putty / SecureCRT / Xshell / FinalShell）</td><td>远程连接工具</td></tr><tr><td>16</td><td>FinalShell 安装</td><td>FinalShell 安装</td></tr><tr><td>17</td><td>FinalShell 连接 Linux（新建 SSH 连接）</td><td>FinalShell 连接虚拟机</td></tr><tr><td>18</td><td>小节页——重复第 6 页</td><td>目录介绍</td></tr><tr><td>19</td><td>Linux 目录 VS Windows 目录（/ 是顶点、倒挂的树）</td><td>Linux 的目录结构</td></tr><tr><td>20</td><td>Linux 目录结构（12 个目录各自放什么）</td><td>12 个目录逐个说</td></tr><tr><td>21</td><td>问答页：<code>/itheima</code> 与 <code>itheima</code> 有区别吗</td><td>绝对路径与相对路径</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p><strong>课程环境是 CentOS 7，本站实测环境是 Ubuntu 24.04（WSL）</strong>——这一章后面的命令、软件安装、防火墙，课程里讲的都是 CentOS 那一套（<code>yum</code>、<code>systemctl</code>、<code>firewalld</code>），而本机实测用的是 Ubuntu（<code>apt</code>、<code>ufw</code>）。<strong>命令的行为可以照着看，包管理和防火墙的命令别混着抄</strong>。凡是引用实测的地方，本篇都会写清是哪种环境。</p></div><h2 id="从打包完成到-真上线-ppt-第-1-5-页" tabindex="-1">从打包完成到&quot;真上线&quot;（PPT 第 1～5 页） <a class="header-anchor" href="#从打包完成到-真上线-ppt-第-1-5-页" aria-label="Permalink to &quot;从打包完成到&quot;真上线&quot;（PPT 第 1～5 页）&quot;">​</a></h2><p>第 1 页是课程封面，第 2 页是<strong>整门课的全景图</strong>——这张图把 JavaWeb 的全部内容分成五块：</p><table tabindex="0"><thead><tr><th>阶段</th><th>包含的技术</th></tr></thead><tbody><tr><td>Web 前端基础</td><td>HTML、CSS、JavaScript</td></tr><tr><td>Web 前端实战</td><td>Vue3、Ajax/Axios、Vue 工程化、ElementPlus</td></tr><tr><td>Web 后端基础</td><td>Maven、Web 基础知识、MySQL、JDBC、MyBatis</td></tr><tr><td>Web 后端实战</td><td>Tlias 案例（以及第 13～18 章的一堆真实业务模块）</td></tr><tr><td><strong>Web 项目部署</strong></td><td><strong>Linux、Docker</strong></td></tr></tbody></table><p>前四块我们已经走完了（前端从 <a href="/posts/编程学习/javaweb学习笔记/03-html快速入门/">3 篇</a>一路到 <a href="/posts/编程学习/javaweb学习笔记/105-前端打包部署/">105 篇</a>，后端从 Maven 到 Tlias 项目实战），<strong>现在站在最后一块上</strong>。第 3 页就是这一块的章节标题：&quot;<strong>项目部署(Linux)</strong>&quot;。</p><p>第 5 页给出第 19 章的目录，四节依次是：</p><table tabindex="0"><thead><tr><th>第 19 章的小节</th><th>PPT 页</th><th>会写成本站的哪一篇</th></tr></thead><tbody><tr><td>Linux 概述</td><td>1～21</td><td><strong>本篇（106）</strong></td></tr><tr><td>Linux 常用命令</td><td>22～51</td><td><a href="/posts/编程学习/javaweb学习笔记/107-linux常用命令/">107 篇</a></td></tr><tr><td>Linux 软件安装</td><td>52～62</td><td>108 篇</td></tr><tr><td>项目部署</td><td>63～70</td><td>109 篇</td></tr></tbody></table><p>第 19 章结束后还有第 20 章（Docker）——同样是&quot;项目部署&quot;，但玩法和这一章完全不同（110～113 篇）。</p><h2 id="操作系统分类与-为什么后端要学-linux-ppt-第-4-页" tabindex="-1">操作系统分类与&quot;为什么后端要学 Linux&quot;（PPT 第 4 页） <a class="header-anchor" href="#操作系统分类与-为什么后端要学-linux-ppt-第-4-页" aria-label="Permalink to &quot;操作系统分类与&quot;为什么后端要学 Linux&quot;（PPT 第 4 页）&quot;">​</a></h2><p>第 4 页先给 Linux 下定义，再给出这张<strong>必须记住的分类表</strong>：</p><blockquote><p><strong>Linux</strong>：Linux 是一套<strong>免费使用和自由传播</strong>的操作系统。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>系统</th><th>特点</th></tr></thead><tbody><tr><td><strong>桌面操作系统</strong></td><td>Windows</td><td>用户数量最多</td></tr><tr><td></td><td>Mac OS</td><td>操作体验好，办公人士首选</td></tr><tr><td></td><td>Linux</td><td>用户数量少</td></tr><tr><td><strong>移动设备操作系统</strong></td><td>Android</td><td>基于 Linux、开源，主要用于智能手机、平板、智能电视</td></tr><tr><td></td><td>IOS</td><td>苹果公司开发、不开源，用于苹果公司的产品</td></tr><tr><td></td><td>HarmonyOS</td><td>华为公司开发、开源，目前用于华为公司的产品</td></tr><tr><td><strong>服务器操作系统</strong></td><td>Unix</td><td>安全、稳定、付费</td></tr><tr><td></td><td>Linux</td><td><strong>安全、稳定、免费、占有率高</strong></td></tr><tr><td></td><td>Windows Server</td><td>付费、占有率低</td></tr></tbody></table><p>这张表要看懂的是<strong>同一个名字在不同场景里的地位完全不同</strong>：Linux 在桌面场景是&quot;用户数量少&quot;（普通人不用），在移动端是 Android 的底座，而在<strong>服务器场景</strong>它是&quot;安全、稳定、免费、占有率高&quot;——这个&quot;占有率高&quot;就是后端必须学它的原因。</p><p>PPT 第 4 页右下角还配了这张图里最实际的两句话：</p><blockquote><p><strong>软件环境（mysql、redis、MQ）+ 项目部署</strong></p></blockquote><p>翻译一下就是：<strong>公司买来（或租来）的那台服务器上装的几乎都是 Linux</strong>，我们要把三样东西放上去——</p><ol><li><strong>中间件</strong>：MySQL（数据库）、Redis（缓存）、MQ（消息队列），它们都得在 Linux 上装、在 Linux 上跑；</li><li><strong>后端项目</strong>：Tlias 那种 SpringBoot 工程打成 jar，也在 Linux 上跑（<a href="/posts/编程学习/javaweb学习笔记/57-tlias项目准备与开发规范/">57 篇</a>里它还在自己电脑的 8080 上）；</li><li><strong>前端静态资源</strong>：就是 <a href="/posts/编程学习/javaweb学习笔记/105-前端打包部署/">105 篇</a>打包出来的那份 <code>dist</code>，交给 Linux 上的 nginx 发。</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>一句话记住这个理由：<strong>写代码可以挑系统，部署项目没得挑</strong>。你本机是 Windows 还是 Mac 都行，但项目上线的那台机器是 Linux，所以 Linux 的登录、传文件、装软件、看日志、启停服务这一套必须会——这就是第 19 章存在的意义。</p></div><h2 id="linux-的内核版与发行版-ppt-第-6-7-页" tabindex="-1">Linux 的内核版与发行版（PPT 第 6～7 页） <a class="header-anchor" href="#linux-的内核版与发行版-ppt-第-6-7-页" aria-label="Permalink to &quot;Linux 的内核版与发行版（PPT 第 6～7 页）&quot;">​</a></h2><p>第 6 页是小节页（&quot;<strong>Linux 概述 01</strong>&quot;，下面三个子项：<strong>系统安装 / 远程连接 / 目录介绍</strong>）——本篇后面就按这三件事往下讲。</p><p>第 7 页讲 Linux 的版本，第一句是结论：<strong>Linux 系统分为内核版和发行版</strong>。</p><table tabindex="0"><thead><tr><th></th><th>内核版（Kernel）</th><th>发行版（Distribution）</th></tr></thead><tbody><tr><td><strong>谁开发、谁维护</strong></td><td>由 Linux <strong>核心团队</strong>开发、维护</td><td>基于 Linux 内核版<strong>进行扩展</strong>，由各个 <strong>Linux 厂商</strong>开发、维护</td></tr><tr><td><strong>收费情况</strong></td><td><strong>免费、开源</strong></td><td><strong>有收费版本，也有免费版本</strong></td></tr><tr><td><strong>职责</strong></td><td>负责<strong>控制硬件</strong></td><td>在内核之上打包出完整可用的系统（工具、软件包、界面等）</td></tr></tbody></table><p>打个不严谨但好懂的比方：<strong>内核版是&quot;发动机&quot;，发行版是整辆车</strong>。发动机只有一套（Linux 核心团队维护的内核），但各家厂商拿它造出了外观、配置、价格都不同的车。</p><p>PPT 第 7 页列了 <strong>6 个常见发行版</strong>：</p><table tabindex="0"><thead><tr><th>发行版</th><th>特点</th></tr></thead><tbody><tr><td><strong>Ubuntu</strong></td><td>以桌面应用为主，免费</td></tr><tr><td><strong>RedHat</strong></td><td>面向企业用户，<strong>收费</strong></td></tr><tr><td><strong>CentOS</strong></td><td><strong>RedHat 的社区版，免费</strong></td></tr><tr><td><strong>Fedora</strong></td><td>功能完备、快速更新，免费</td></tr><tr><td><strong>openSUSE</strong></td><td>对个人完全免费、图形界面华丽</td></tr><tr><td><strong>红旗 Linux</strong></td><td>北京中科红旗软件技术有限公司开发</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p><strong>课程用的是 CentOS 7</strong>（表中第三个）：它和收费的 RedHat 同源、免费、公司里用得多——&quot;企业里在用的、又不用花钱的&quot;，就是它适合教学的原因。这个选择决定了后面所有命令的样子：<strong>包管理是 <code>yum</code>、防火墙是 <code>firewalld</code>、服务管理是 <code>systemctl</code></strong>（<a href="/posts/编程学习/javaweb学习笔记/108-linux软件安装/">108 篇</a>那一套软件安装就全建立在 CentOS 之上）。</p><p>本机实测环境恰好是一台 <strong>Ubuntu 24.04</strong>，所以本篇最后会专门列一张&quot;两个发行版的命令差异表&quot;，避免把两边的命令抄串。</p></div><h2 id="装-linux-的两条路-物理机与虚拟机-ppt-第-8-页" tabindex="-1">装 Linux 的两条路：物理机与虚拟机（PPT 第 8 页） <a class="header-anchor" href="#装-linux-的两条路-物理机与虚拟机-ppt-第-8-页" aria-label="Permalink to &quot;装 Linux 的两条路：物理机与虚拟机（PPT 第 8 页）&quot;">​</a></h2><p>第 8 页把安装方式分成两种：</p><blockquote><ul><li><strong>物理机安装</strong>：直接将操作系统安装到<strong>服务器硬件</strong>上</li><li><strong>虚拟机安装</strong>：通过<strong>虚拟机软件</strong>安装</li></ul></blockquote><p><strong>物理机安装</strong>就是&quot;整台机器只有一个系统&quot;：买一台服务器，把 Linux 装在它的硬盘上，开机就是 Linux。生产环境正式上线都是这么干的。</p><p><strong>虚拟机安装</strong>则是先给&quot;虚拟机&quot;下定义：</p><blockquote><p><strong>虚拟机（Virtual Machine）<strong>指通过软件模拟的具有</strong>完整硬件系统功能</strong>、运行在<strong>完全隔离环境</strong>中的完整计算机系统。</p></blockquote><p>也就是说：<strong>用软件在自己电脑上&quot;模拟&quot;出一台完整的电脑</strong>——它有自己虚拟的 CPU、内存、硬盘、网卡，可以在里面装一个和 Windows 完全隔离的 Linux。原机上的 Windows 一点不受影响，虚拟机里哪怕把系统搞坏了，删掉重装就行。</p><p>PPT 第 8 页列了三款虚拟机软件：</p><table tabindex="0"><thead><tr><th>虚拟机软件</th><th>说明</th></tr></thead><tbody><tr><td><strong>VMWare WorkStation</strong></td><td>课程用的就是它</td></tr><tr><td><strong>VirtualBox</strong></td><td>免费开源的那款</td></tr><tr><td><strong>VMLite WorkStation</strong></td><td>更轻量的选择</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/08-%E6%9C%8D%E5%8A%A1%E5%99%A8%E7%A1%AC%E4%BB%B6.jpg" alt="服务器硬件"><em>图：PPT 第 8 页配的服务器实物——&quot;物理机安装&quot;就是把操作系统<strong>直接装到这样一台机器的硬件上</strong>；而学习阶段手上只有一台笔记本/台式机，所以走&quot;虚拟机安装&quot;这条路，用软件在这台电脑里再&quot;造&quot;出一台机器来</em></p><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p><strong>为什么学习阶段一定要用虚拟机</strong>（PPT 没说、但每个踩过坑的人都懂的三条理由）：① <strong>不破坏本机</strong>——装系统、删软件、改配置随便折腾，坏了删掉重来；② <strong>可以随时&quot;回到过去&quot;</strong>——虚拟机支持快照，装完一个干净的 CentOS 7 先拍一张，之后怎么乱搞都能回滚；③ <strong>本机 Windows 要留着开发</strong>——IDEA、Node、浏览器都在上面，Linux 只是&quot;另一台机器&quot;。</p><p>本篇实测用的 WSL 是<strong>另一种</strong>思路（Windows 内嵌的 Linux 子系统，见下文&quot;本机实测&quot;）：它更轻、启动更快，但没有完整虚拟机那套&quot;装系统 / 挂镜像 / 配网卡&quot;的过程——<strong>课程实验还是要按 PPT 在 VMware 里做</strong>。</p></div><h2 id="装-vmware-与-挂载-centos-7-镜像-ppt-第-9、11-页" tabindex="-1">装 VMware 与&quot;挂载&quot;CentOS 7 镜像（PPT 第 9、11 页） <a class="header-anchor" href="#装-vmware-与-挂载-centos-7-镜像-ppt-第-9、11-页" aria-label="Permalink to &quot;装 VMware 与&quot;挂载&quot;CentOS 7 镜像（PPT 第 9、11 页）&quot;">​</a></h2><p>安装 VMware 这一步 PPT 只写了一句话：</p><blockquote><p><strong>虚拟机安装</strong>：直接双击运行资料中的 VMWare 安装程序，根据提示完成安装即可。</p></blockquote><p><img src="https://img.tsh520.cn/file/blog/article/09-VMware%E5%AE%89%E8%A3%85%E5%90%91%E5%AF%BC.jpg" alt="VMware 安装向导"><em>图：PPT 第 9 页配的安装界面——<strong>VMware Workstation Pro 16</strong> 的安装向导第一步，&quot;下一步 / 取消&quot;。安装过程没有需要特别设置的地方：接受许可、选安装目录（想省 C 盘空间就换到 D 盘）、一路下一步，最后重启一下</em></p><p>第 11 页是<strong>挂载镜像</strong>（把老师给的 CentOS 7 虚拟机文件&quot;挂&quot;到 VMware 里）：</p><blockquote><p>解压 CentOS7 的镜像压缩包到磁盘目录，然后<strong>双击 .vmx 文件</strong>完成挂载，然后<strong>启动服务器（root/1234）</strong>。</p></blockquote><p>三步拆开看：</p><p><strong>① 解压镜像包到磁盘目录</strong>——把资料里的 CentOS7 压缩包解压出来，会看到一个目录（PPT 图里是 <code>D:\\VMimages\\CentOS7-1</code>），里面是一堆虚拟机文件：</p><p><img src="https://img.tsh520.cn/file/blog/article/11-%E5%8F%8C%E5%87%BBvmx%E5%AE%8C%E6%88%90%E6%8C%82%E8%BD%BD.jpg" alt="双击 vmx 完成挂载"><em>图：PPT 第 11 页配的解压结果——<code>CentOS 7 64 位.vmx</code>（红色箭头指的那个，图标上带着 VMware 的标志）是整台虚拟机的&quot;入口文件&quot;，<code>.vmdk</code> 是虚拟硬盘（一台机器可能被切成 s001～s013 好几个）、<code>.nvram</code> / <code>.vmsd</code> 是状态与快照文件。<strong>这一堆文件都不能删、不能单独移动，要动就整个文件夹一起动</strong></em></p><p><strong>② 双击 <code>.vmx</code> 完成挂载</strong>——双击之后 Windows 会问&quot;用什么打开&quot;，选 <strong>VMware Workstation</strong>：</p><p><img src="https://img.tsh520.cn/file/blog/article/11-%E9%80%89%E6%8B%A9VMware%E6%89%93%E5%BC%80vmx.jpg" alt="选择 VMware 打开 vmx"><em>图：PPT 第 11 页配的&quot;你要如何打开这个文件?&quot;对话框——选 <strong>VMware Workstation</strong> 并勾上&quot;始终使用此应用打开 .vmx 文件&quot;，之后再双击就直接进 VMware 了（第一次没勾的话，每次都要再选一遍）</em></p><p><strong>③ 启动服务器</strong>——这台虚拟机就被&quot;挂&quot;进 VMware 的列表里了，点&quot;<strong>开启此虚拟机</strong>&quot;开机：</p><p><img src="https://img.tsh520.cn/file/blog/article/11-%E5%BC%80%E5%90%AF%E6%AD%A4%E8%99%9A%E6%8B%9F%E6%9C%BA.jpg" alt="开启此虚拟机"><em>图：PPT 第 11 页配的 VMware 界面——左侧是这台机器的设备清单（内存 4 GB、处理器 2 个、硬盘 50 GB、<strong>网络适配器 NAT</strong>、CD/DVD 正在使用文件……），右侧中间那个红箭头指向的按钮就是&quot;<strong>开启此虚拟机</strong>&quot;；底部&quot;虚拟机详细信息&quot;里能看到配置文件路径（<code>.vmx</code>）和&quot;状态：已关机&quot;</em></p><p>开机之后要登录：<strong>用户名 <code>root</code>，密码 <code>1234</code></strong>（PPT 原文给的）。<code>root</code> 是 Linux 的<strong>超级管理员</strong>，相当于 Windows 的 Administrator——后面 <a href="/posts/编程学习/javaweb学习笔记/108-linux软件安装/">108 篇</a>装软件、<a href="/posts/编程学习/javaweb学习笔记/109-项目部署到linux/">109 篇</a>部署项目，用的都是这个账号。</p><h2 id="虚拟机网络配置-nat-模式与查-ip-ppt-第-10、12-页" tabindex="-1">虚拟机网络配置：NAT 模式与查 IP（PPT 第 10、12 页） <a class="header-anchor" href="#虚拟机网络配置-nat-模式与查-ip-ppt-第-10、12-页" aria-label="Permalink to &quot;虚拟机网络配置：NAT 模式与查 IP（PPT 第 10、12 页）&quot;">​</a></h2><p>装完系统只是&quot;这台机器能开机了&quot;，PPT 第 10 页紧接着说：</p><blockquote><p>安装完毕之后，需要<strong>配置网络</strong>，才可以在 windows 系统上连接虚拟机上的 linux 系统。</p></blockquote><p>为什么非要配网络？因为默认情况下虚拟机可能<strong>没有 IP</strong>——没有 IP，Windows 就没法&quot;够到&quot;它，自然也谈不上后面用 FinalShell 连上去。</p><p>第 12 页把配置过程写成了三件事：</p><blockquote><ul><li><strong>虚拟网络编辑器 → NAT 模式 → 子网 IP：设置为 <code>192.168.100.0</code></strong></li><li>查看 IP 地址的命令：<strong><code>ip addr</code></strong>；如果没有 IP 地址：执行 <strong><code>start-ens33.sh</code></strong> 脚本，手动激活 <strong>ens33</strong> 网卡</li><li>启动/停止/重启 Linux 系统：<strong>图形化界面 / 命令（<code>init 0</code>：关闭，<code>init 6</code>：重启）</strong></li></ul></blockquote><h3 id="_1-在-vmware-里认出虚拟网卡" tabindex="-1">① 在 VMware 里认出虚拟网卡 <a class="header-anchor" href="#_1-在-vmware-里认出虚拟网卡" aria-label="Permalink to &quot;① 在 VMware 里认出虚拟网卡&quot;">​</a></h3><p>虚拟网络编辑器藏在 VMware 的菜单里：</p><p><img src="https://img.tsh520.cn/file/blog/article/10-%E8%99%9A%E6%8B%9F%E7%BD%91%E7%BB%9C%E7%BC%96%E8%BE%91%E5%99%A8%E5%85%A5%E5%8F%A3.jpg" alt="虚拟网络编辑器入口"><em>图：PPT 第 10 页配的位置图——VMware 的菜单栏&quot;<strong>编辑(E) → 虚拟网络编辑器(N)...</strong>&quot;，就是从这里进去改虚拟机用的那张&quot;虚拟网卡&quot;</em></p><p><img src="https://img.tsh520.cn/file/blog/article/10-NAT%E6%A8%A1%E5%BC%8F%E4%B8%8E%E5%AD%90%E7%BD%91IP.jpg" alt="NAT 模式与子网 IP"><em>图：PPT 第 10、12 页配的核心设置界面——上半张表里 <strong>VMnet8</strong> 的类型是&quot;<strong>NAT 模式</strong>&quot;（<code>VMnet8</code> 就是 VMware 给 NAT 模式准备的虚拟网卡，<code>VMnet1</code> 是仅主机模式，<code>VMnet0</code> 是桥接）；下半部分是它的详细设置：勾着 <strong>NAT 模式（用于共享主机的 IP 地址）</strong>，下面的&quot;<strong>子网 IP (I)：192.168.100.0</strong>&quot;和&quot;子网掩码 255.255.255.0&quot;就是 PPT 第 12 页要求改的那一项。改完点&quot;应用 / 确定&quot;</em></p><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p><strong>为什么是 NAT 模式、为什么是 <code>192.168.100.0</code> 这个网段</strong>：</p><ul><li><strong>NAT（网络地址转换）</strong>：虚拟机相当于&quot;蹭&quot;主机的网络出去——虚拟机能上网、主机能访问虚拟机，但外面看不进来。用在练习机上最省心：不用管公司/家里的网段是什么、换 WiFi 也不用重配。</li><li><strong><code>192.168.100.0/24</code></strong> 是一个<strong>私有网段</strong>（<code>192.168.x.x</code> 都是局域网地址，不会和公网冲突）。课程把它统一成 <code>192.168.100.0</code>，原因很实在：<strong>全班同学、所有 PPT 截图、老师演示的 IP 就都是同一串</strong>（后面最终会看到虚拟机拿到 <code>192.168.100.128</code> 这样的地址），照着抄不会错。</li><li>要远离的两件事：别选&quot;<strong>桥接模式</strong>&quot;（那样虚拟机会直接接进你所在的实际网络、抢路由器的 IP，IP 说变就变）；也别随手把网段改成和自己家路由器一样的（可能和真实网卡撞车）。</li></ul></div><h3 id="_2-进-linux-里查-ip" tabindex="-1">② 进 Linux 里查 IP <a class="header-anchor" href="#_2-进-linux-里查-ip" aria-label="Permalink to &quot;② 进 Linux 里查 IP&quot;">​</a></h3><p>网络配好之后，进虚拟机的桌面/终端执行 PPT 给的那条命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 查看本机所有网卡的 IP 地址（CentOS 7 自带；旧系统里对应的是 ifconfig）</span></span></code></pre></div><p><code>ens33</code> 是这台 CentOS 7 的<strong>网卡名</strong>（<code>en</code> = ethernet 以太网、<code>s33</code> 是这块网卡在机器里的编号），输出里会看到它拿到了一个 <code>192.168.100.x</code> 的地址。</p><p><strong>如果 <code>ip addr</code> 里没有 IP</strong>（<code>ens33</code> 那一块看不到 <code>inet 192.168.100.x</code>），就按 PPT 说的执行资源包里的脚本，手动把网卡激活：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start-ens33.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 手动激活 ens33 网卡（老师给的脚本，通常内部是在启动网卡并让 dhcp 重新取地址）</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>课程环境下&quot;没有 IP&quot;最常见的原因就一个：<strong>CentOS 7 的网卡默认没开机自启</strong>，装完之后得手动激活一次。</p></div><h3 id="_3-关机和重启" tabindex="-1">③ 关机和重启 <a class="header-anchor" href="#_3-关机和重启" aria-label="Permalink to &quot;③ 关机和重启&quot;">​</a></h3><p>PPT 还顺带给了两个&quot;用命令开关机&quot;的写法：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>说明</th></tr></thead><tbody><tr><td><code>init 0</code></td><td><strong>关机</strong></td><td>不用去点图形界面的按钮，直接敲命令</td></tr><tr><td><code>init 6</code></td><td><strong>重启</strong></td><td>改完配置要重启时用</td></tr></tbody></table><p>图形界面里当然也能点（右上角电源按钮），但<strong>远程连上去之后就只剩命令这条路了</strong>——这两个命令要记住。</p><h2 id="本机实测-一台真实的-linux-长什么样-wsl-ubuntu-24-04" tabindex="-1">本机实测：一台真实的 Linux 长什么样（WSL Ubuntu 24.04） <a class="header-anchor" href="#本机实测-一台真实的-linux-长什么样-wsl-ubuntu-24-04" aria-label="Permalink to &quot;本机实测：一台真实的 Linux 长什么样（WSL Ubuntu 24.04）&quot;">​</a></h2><blockquote><p>本节输出全部来自本机实测：<strong>WSL（Windows Subsystem for Linux）里的 Ubuntu 24.04.3 LTS，内核 6.6.87.2-microsoft-standard-WSL2</strong>。WSL 是&quot;Windows 里内嵌的 Linux&quot;，不是 VMware 那种完整虚拟机，但<strong>命令行行为与虚拟机里的 Linux 完全一致</strong>，用来验证命令足够。</p></blockquote><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">6.6.87.2-microsoft-standard-WSL2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 内核版本</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/os-release</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 发行版信息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PRETTY_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ubuntu 24.04.3 LTS&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ubuntu&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VERSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;24.04.3 LTS (Noble Numbat)&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                 # 当前登录的用户</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dumplingandcake</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 这四个软件装在哪儿（只回显已安装的）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/usr/bin/vim</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                             # 只有 vim 装了，java / nginx / mysql 都没有</span></span></code></pre></div><p>这四条命令正好对上本篇几个知识点：</p><table tabindex="0"><thead><tr><th>实测的东西</th><th>说明什么</th></tr></thead><tbody><tr><td><code>uname -r</code> → <code>6.6.87.2-microsoft-standard-WSL2</code></td><td>这就是<strong>内核版</strong>——一台机器只有一个内核，Linux 核心团队维护；后面的&quot;发行版&quot;才是各家厂商的包装</td></tr><tr><td><code>cat /etc/os-release</code> → <code>Ubuntu 24.04.3 LTS</code></td><td>这是<strong>发行版</strong>信息：<strong>课程环境是 CentOS 7，本机是 Ubuntu 24.04</strong>，两边的&quot;厂商&quot;不同</td></tr><tr><td><code>whoami</code> → <code>dumplingandcake</code></td><td>当前登录的是普通用户 <code>dumplingandcake</code>（家目录 <code>/home/dumplingandcake</code>）；而课程里用的是<strong>超级管理员 <code>root</code></strong>（家目录 <code>/root</code>），权限完全不同</td></tr><tr><td><code>which java nginx mysql vim</code> → 只有 <code>/usr/bin/vim</code></td><td>这台机器上<strong>只有 vim</strong>，后面 108 篇要装的 JDK、MySQL、Nginx 一个都没有——正好可以从零演示一遍&quot;软件安装&quot;</td></tr></tbody></table><h3 id="centos-7-与-ubuntu-24-04-的命令差异表" tabindex="-1">CentOS 7 与 Ubuntu 24.04 的命令差异表 <a class="header-anchor" href="#centos-7-与-ubuntu-24-04-的命令差异表" aria-label="Permalink to &quot;CentOS 7 与 Ubuntu 24.04 的命令差异表&quot;">​</a></h3><p>因为课程环境（CentOS 7）和实测环境（Ubuntu 24.04）是两个不同的发行版，下面这些&quot;<strong>换了个发行版就不一样</strong>&quot;的地方要提前分清：</p><table tabindex="0"><thead><tr><th>事情</th><th>课程环境 CentOS 7</th><th>本机实测 Ubuntu 24.04</th></tr></thead><tbody><tr><td>装软件（包管理）</td><td><strong><code>yum</code></strong>（如 <code>yum install vim</code>）</td><td><code>apt</code>（如 <code>apt install vim</code>）</td></tr><tr><td>防火墙</td><td><strong><code>firewalld</code></strong>（<code>firewall-cmd</code>，<a href="/posts/编程学习/javaweb学习笔记/108-linux软件安装/">108 篇</a>要考）</td><td><code>ufw</code></td></tr><tr><td>管理服务</td><td><code>systemctl start/stop/status xxx</code>（<a href="/posts/编程学习/javaweb学习笔记/108-linux软件安装/">108 篇</a>用得上）</td><td>同样有 <code>systemctl</code>（WSL 里默认没开 systemd，情况特殊）</td></tr><tr><td><code>ll</code> 这个简写</td><td><strong>能用</strong>（PPT 第 25 页明说了 <code>ll</code> 是 <code>ls -l</code> 的简写）</td><td><strong>默认没有</strong>，得写 <code>ls -l</code>（<a href="/posts/编程学习/javaweb学习笔记/107-linux常用命令/">107 篇</a>实测里就踩到这一点）</td></tr><tr><td>查看网卡 IP</td><td><code>ip addr</code>（一样）</td><td><code>ip addr</code>（一样）</td></tr></tbody></table><p>其余命令（<code>cd</code>、<code>mkdir</code>、<code>cp</code>、<code>mv</code>、<code>tar</code>、<code>find</code>、<code>grep</code>、<code>vi/vim</code>……）<strong>两个发行版完全一样</strong>——这部分占了第 19 章的大半，也是 <a href="/posts/编程学习/javaweb学习笔记/107-linux常用命令/">107 篇</a>的全部内容。</p><h2 id="远程连接-从-windows-连上-linux-ppt-第-13-17-页" tabindex="-1">远程连接：从 Windows 连上 Linux（PPT 第 13～17 页） <a class="header-anchor" href="#远程连接-从-windows-连上-linux-ppt-第-13-17-页" aria-label="Permalink to &quot;远程连接：从 Windows 连上 Linux（PPT 第 13～17 页）&quot;">​</a></h2><h3 id="为什么需要远程连接-ppt-第-13-页" tabindex="-1">为什么需要远程连接（PPT 第 13 页） <a class="header-anchor" href="#为什么需要远程连接-ppt-第-13-页" aria-label="Permalink to &quot;为什么需要远程连接（PPT 第 13 页）&quot;">​</a></h3><p>第 13 页抛了一个真实场景的问题：</p><blockquote><p><strong>公司在北京，服务器可能在上海/天津/香港/海外，该如何进行软件安装/项目部署？</strong></p></blockquote><p><img src="https://img.tsh520.cn/file/blog/article/13-%E6%9C%BA%E6%88%BF%E9%87%8C%E7%9A%84%E6%9C%8D%E5%8A%A1%E5%99%A8.jpg" alt="机房里的服务器"><em>图：PPT 第 13 页配的机房照片——服务器躺在<strong>机房</strong>里，人在办公室，中间隔着城市甚至国界。总不可能背着显示器键盘飞过去装软件：所以<strong>能操作到的只有网络</strong>，这就是&quot;远程连接&quot;要解决的问题</em></p><p>答案就是<strong>远程连接</strong>：服务器在哪儿不重要，只要能通过网络连到它的 <strong>22 端口</strong>，在自己的电脑上敲命令，效果和坐在它面前一模一样。</p><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>这里的&quot;远程连接&quot;和以后工作里的场景是同一件事：测试环境、预发布环境、生产环境，每台机器都在机房里，日常操作（启服务、传 jar、看日志、改配置）<strong>全是在自己的电脑上通过远程连接工具完成的</strong>。所以这套东西不是&quot;课程演示用一下&quot;，是<strong>上班之后的日常工具</strong>。</p></div><h3 id="ssh-与四种远程连接工具-ppt-第-15-页" tabindex="-1">SSH 与四种远程连接工具（PPT 第 15 页） <a class="header-anchor" href="#ssh-与四种远程连接工具-ppt-第-15-页" aria-label="Permalink to &quot;SSH 与四种远程连接工具（PPT 第 15 页）&quot;">​</a></h3><blockquote><p>常用的 **SSH（Secure Shell，安全外壳协议）**远程连接工具：<strong>Putty、SecureCRT、Xshell、FinalShell</strong> 等。</p></blockquote><p>拆两点：</p><ol><li><strong>SSH 是&quot;协议&quot;</strong>（双方约定好的一套通信规则），规定了怎么加密、怎么认证、怎么开一个远程终端。一个 Linux 服务器只要装了 SSH 服务（sshd 默认就开着、监听 22 端口），任何支持 SSH 的客户端都能连它。</li><li><strong>Putty / SecureCRT / Xshell / FinalShell 是&quot;客户端软件&quot;</strong>——相当于同一个协议的四个不同&quot;电话机&quot;。它们都是远程连接工具，区别在功能和界面：</li></ol><table tabindex="0"><thead><tr><th>工具</th><th>特点</th></tr></thead><tbody><tr><td>Putty</td><td>老牌、极轻量，功能最基础</td></tr><tr><td>SecureCRT</td><td>商业软件，功能强、企业里常见</td></tr><tr><td>Xshell</td><td>界面友好、Windows 上很流行</td></tr><tr><td><strong>FinalShell</strong></td><td><strong>国产、免费、带上传下载和服务器监控</strong>——课程用它</td></tr></tbody></table><p><strong>课程选 FinalShell 的现实原因</strong>：它自带&quot;<strong>文件上传/下载</strong>&quot;面板（后面 <a href="/posts/编程学习/javaweb学习笔记/108-linux软件安装/">108 篇</a>要把 JDK、MySQL、Nginx 的安装包传到服务器上，<a href="/posts/编程学习/javaweb学习笔记/109-项目部署到linux/">109 篇</a>要传打好的 jar 和前端资源——用鼠标拖进去，比命令简单得多）。</p><h3 id="finalshell-安装-ppt-第-16-页" tabindex="-1">FinalShell 安装（PPT 第 16 页） <a class="header-anchor" href="#finalshell-安装-ppt-第-16-页" aria-label="Permalink to &quot;FinalShell 安装（PPT 第 16 页）&quot;">​</a></h3><blockquote><p>直接双击运行 FinalShell 的安装程序完成安装即可。</p></blockquote><p><img src="https://img.tsh520.cn/file/blog/article/16-FinalShell%E5%AE%89%E8%A3%85%E5%90%91%E5%AF%BC.jpg" alt="FinalShell 安装向导"><em>图：PPT 第 16 页配的安装界面——FinalShell 3.8.3 的安装向导，&quot;最终用户许可协议&quot;这一步（按 PgDn 读完、点&quot;我接受(I)&quot;继续）。同样是一路下一步的普通 Windows 安装，不需要额外配置</em></p><h3 id="finalshell-连接虚拟机-ppt-第-17-页" tabindex="-1">FinalShell 连接虚拟机（PPT 第 17 页） <a class="header-anchor" href="#finalshell-连接虚拟机-ppt-第-17-页" aria-label="Permalink to &quot;FinalShell 连接虚拟机（PPT 第 17 页）&quot;">​</a></h3><p>装完之后就是<strong>配一个连接</strong>，让它去连我们刚装好的那台 CentOS 7。数据来自网络配置那一步查到的 IP（PPT 里的机器是 <code>192.168.100.128</code>）：</p><p><img src="https://img.tsh520.cn/file/blog/article/17-FinalShell%E6%96%B0%E5%BB%BASSH%E8%BF%9E%E6%8E%A5.jpg" alt="FinalShell 新建 SSH 连接"><em>图：PPT 第 17 页配的&quot;新建连接&quot;对话框——左侧树里选的是 <strong>SSH 连接</strong>（下面还有&quot;终端 / 代理服务器 / 隧道&quot;可展开）；右侧&quot;常规&quot;里 <strong>名称和主机都填虚拟机的 IP <code>192.168.100.128</code></strong>、&quot;端口 <strong>22</strong>&quot;（SSH 的默认端口）；&quot;认证&quot;里方法选<strong>密码</strong>、<strong>用户名 <code>root</code></strong>、<strong>密码</strong>（课程里就是 <code>1234</code>）。填完点确定</em></p><p>配好的连接会出现在连接管理器里，双击就能连上：</p><p><img src="https://img.tsh520.cn/file/blog/article/17-FinalShell%E8%BF%9E%E6%8E%A5%E7%AE%A1%E7%90%86%E5%99%A8.jpg" alt="FinalShell 连接管理器"><em>图：PPT 第 17 页配的连接管理器——列表里躺着配好的连接（<code>192.168.100.128</code>、端口 <code>22</code>、用户 <code>root</code>），右键或双击即可打开一个远程终端；下面还勾着&quot;连接后关闭窗口&quot;。连上之后，<strong>面板里敲的命令 = 在虚拟机里敲的命令</strong>，接下来 <a href="/posts/编程学习/javaweb学习笔记/107-linux常用命令/">107 篇</a>的所有命令都可以在这里练</em></p><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p>连不上时的排查顺序（这三条覆盖了 90% 的情况）：① <strong>虚拟机的 IP 对不对</strong>——进虚拟机执行 <code>ip addr</code>，看 <code>ens33</code> 有没有 <code>192.168.100.x</code>，没 IP 就先激活网卡；② <strong>本机的虚拟网卡在不在</strong>——Windows 的&quot;网络连接&quot;里要有 <strong>VMware Network Adapter VMnet8</strong>，装完 VMware 一般自动就有（对应 PPT 第 10 页那张&quot;将主机虚拟适配器连接到此网络&quot;的勾）；③ <strong>虚拟机开机了没</strong>——VMware 里点&quot;开启此虚拟机&quot;，别停在关机状态。</p></div><h2 id="linux-的目录结构-ppt-第-18-20-页" tabindex="-1">Linux 的目录结构（PPT 第 18～20 页） <a class="header-anchor" href="#linux-的目录结构-ppt-第-18-20-页" aria-label="Permalink to &quot;Linux 的目录结构（PPT 第 18～20 页）&quot;">​</a></h2><p>第 18 页又是那张小节页（<strong>Linux 概述 01</strong>），下面进入第三件事：<strong>目录介绍</strong>。</p><h3 id="linux-目录-vs-windows-目录-ppt-第-19-页" tabindex="-1">Linux 目录 VS Windows 目录（PPT 第 19 页） <a class="header-anchor" href="#linux-目录-vs-windows-目录-ppt-第-19-页" aria-label="Permalink to &quot;Linux 目录 VS Windows 目录（PPT 第 19 页）&quot;">​</a></h3><blockquote><p><strong>Linux 系统中的目录特点</strong>：</p><ul><li><code>/</code> 是所有目录的<strong>顶点</strong></li><li>目录结构像<strong>一颗倒挂的树</strong></li></ul></blockquote><p>先看 Windows 是怎么组织的：</p><p><img src="https://img.tsh520.cn/file/blog/article/19-Windows%E7%9A%84%E7%A3%81%E7%9B%98%E5%88%86%E5%8C%BA.jpg" alt="Windows 的磁盘分区"><em>图：PPT 第 19 页配的 Windows&quot;此电脑&quot;——<strong>本地磁盘 (C:)、软件 (D:)、文档 (E:)</strong> 三个盘各自独立，每个盘下面都是一棵树。Windows 的目录结构是&quot;<strong>多棵树</strong>&quot;，根是盘符（<code>C:\\</code>、<code>D:\\</code>）</em></p><p>再看 Linux：</p><p><img src="https://img.tsh520.cn/file/blog/article/19-Linux%E7%9B%AE%E5%BD%95%E6%A0%91.jpg" alt="Linux 目录树"><em>图：PPT 第 19 页配的 Linux 根目录——<strong>只有一个根 <code>/</code></strong>，下面挂着一排目录（<code>bin</code>、<code>boot</code>、<code>dev</code>、<code>etc</code>、<code>home</code>、<code>lib</code>、<code>opt</code>、<code>root</code>、<code>sbin</code>、<code>tmp</code>、<code>usr</code>、<code>var</code>……），每个目录下面再套子目录。整台机器<strong>只有这一棵树</strong>，所有文件都在这棵树上的某个位置</em></p><table tabindex="0"><thead><tr><th></th><th>Windows</th><th>Linux</th></tr></thead><tbody><tr><td>有几棵树</td><td><strong>多棵</strong>——每个盘符（C:、D:、E:）一棵</td><td><strong>只有一棵</strong></td></tr><tr><td>树的顶点</td><td>盘符（<code>C:\\</code>、<code>D:\\</code>）</td><td><strong><code>/</code>（根目录）</strong>，它是<strong>所有目录的顶点</strong></td></tr><tr><td>盘去哪了</td><td>就是&quot;根&quot;</td><td><strong>盘被&quot;挂&quot;到树上的某个目录里</strong>（插一块硬盘、U 盘，是把它挂到 <code>/mnt/usb</code> 这样的目录下，不在根上多长出一棵树）</td></tr><tr><td>路径写法</td><td><code>D:\\VMimages\\CentOS7-1\\CentOS 7 64 位.vmx</code></td><td><code>/usr/local/mysql</code>（分隔符是 <code>/</code>，不是 <code>\\</code>）</td></tr></tbody></table><h3 id="_12-个目录逐个说-ppt-第-20-页" tabindex="-1">12 个目录逐个说（PPT 第 20 页） <a class="header-anchor" href="#_12-个目录逐个说-ppt-第-20-页" aria-label="Permalink to &quot;12 个目录逐个说（PPT 第 20 页）&quot;">​</a></h3><p>PPT 第 20 页把根目录下的 12 个目录逐个标了中文说明（<strong>这张表要背，因为它决定了&quot;东西该放哪&quot;</strong>）：</p><table tabindex="0"><thead><tr><th>目录</th><th>放什么</th></tr></thead><tbody><tr><td><strong>bin</strong></td><td>存放<strong>二进制可执行文件</strong>（平时敲的 <code>ls</code>、<code>cd</code>、<code>cp</code> 这些命令本体都在这里）</td></tr><tr><td><strong>boot</strong></td><td>存放<strong>系统引导</strong>时使用的各种文件（内核、启动菜单之类，<strong>别乱动</strong>）</td></tr><tr><td><strong>dev</strong></td><td>存放<strong>设备文件</strong>（Linux 里&quot;一切皆文件&quot;，硬盘、键盘也是文件）</td></tr><tr><td><strong>etc</strong></td><td>存放<strong>系统配置文件</strong>（<a href="/posts/编程学习/javaweb学习笔记/108-linux软件安装/">108 篇</a>要改的 <code>/etc/profile</code> 配环境变量就在这儿）</td></tr><tr><td><strong>home</strong></td><td>存放<strong>系统用户的文件</strong>（普通用户的家目录，形如 <code>/home/用户名</code>）</td></tr><tr><td><strong>lib</strong></td><td>存放程序运行所需的<strong>共享库和内核模块</strong></td></tr><tr><td><strong>opt</strong></td><td><strong>额外安装的可选应用程序包</strong>所放置的位置</td></tr><tr><td><strong>root</strong></td><td><strong>超级用户目录</strong>（root 用户的家目录，注意它就在根下，不在 <code>/home</code> 里）</td></tr><tr><td><strong>sbin</strong></td><td>存放二进制可执行文件，<strong>只有 root 用户才能访问</strong>（<code>s</code> = super，里面是给管理员用的命令）</td></tr><tr><td><strong>tmp</strong></td><td>存放<strong>临时文件</strong>（重启可能被清掉，试验用的东西扔这儿）</td></tr><tr><td><strong>usr</strong></td><td>存放<strong>系统应用程序</strong>（<code>/usr/local</code> 是&quot;后来自己装的软件&quot;的地盘——<a href="/posts/编程学习/javaweb学习笔记/108-linux软件安装/">108 篇</a>装的 JDK、MySQL、Nginx 全在 <code>/usr/local</code> 下）</td></tr><tr><td><strong>var</strong></td><td>存放<strong>运行时需要改变数据的文件</strong>，例如<strong>日志文件</strong>（项目跑起来之后日志一般落在 <code>/var/log</code> 一带）</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/20-Linux%E7%9B%AE%E5%BD%95%E7%BB%93%E6%9E%84%E5%9B%BE.jpg" alt="Linux 目录结构示意图"><em>图：PPT 第 20 页配的目录结构图——最上面是根 <code>/</code>，一层层往下挂：<code>/usr</code> 下有 <code>bin</code>、<code>local</code>、<code>src</code>（自己装的软件在 <code>local</code>、源码包在 <code>src</code>），<code>/etc</code> 下有 <code>rc.d</code> → <code>rc3.d</code> / <code>rc5.d</code> / <code>init.d</code>（系统服务和自启动脚本），左边一列还有 <code>bin</code>、<code>sbin</code>、<code>tmp</code>、<code>lib</code>、<code>var</code>、<code>home</code>、<code>opt</code>。<strong>记住&quot;倒挂的树&quot;这个形状</strong>：越靠上越&quot;系统&quot;，越往下越&quot;具体某个软件自己的东西&quot;</em></p><p>目录为什么重要？因为后面每一篇都在往这些目录里放东西——<strong>装软件放 <code>/usr/local</code>、环境变量改 <code>/etc/profile</code>、日志在 <code>/var/log</code> 一带、自己的试验放 <code>/tmp</code> 或家目录</strong>。位置错了轻则找不到文件，重则覆盖系统的东西。</p><h2 id="绝对路径与相对路径-ppt-第-21-页" tabindex="-1">绝对路径与相对路径（PPT 第 21 页） <a class="header-anchor" href="#绝对路径与相对路径-ppt-第-21-页" aria-label="Permalink to &quot;绝对路径与相对路径（PPT 第 21 页）&quot;">​</a></h2><p>第 21 页是一个问答：</p><blockquote><p><strong>Linux 系统中的路径 <code>/itheima</code> 与 <code>itheima</code> 有区别吗？</strong><strong>有。</strong></p><ul><li><code>/itheima</code> 是<strong>绝对路径</strong>，是指<strong>根目录 <code>/</code> 下的 itheima 目录</strong></li><li><code>itheima</code> 是<strong>相对路径</strong>，是指<strong>当前目录下的 itheima 目录</strong></li></ul></blockquote><p>用一句话概括规则：</p><table tabindex="0"><thead><tr><th>写法</th><th>名字</th><th>从哪儿开始找</th><th>举例（假设当前在 <code>/home/dumplingandcake</code>）</th></tr></thead><tbody><tr><td>以 <strong><code>/</code> 开头</strong></td><td><strong>绝对路径</strong></td><td>从<strong>根目录 <code>/</code></strong> 开始，一层层往下</td><td><code>/itheima</code> → 找 <code>/itheima</code>；<code>/usr/local/mysql</code> → 找根下 <code>usr</code> 里的 <code>local</code> 里的 <code>mysql</code></td></tr><tr><td><strong>不以 <code>/</code> 开头</strong></td><td><strong>相对路径</strong></td><td>从<strong>当前目录</strong>开始</td><td><code>itheima</code> → 找 <code>/home/dumplingandcake/itheima</code></td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p>这是初学者最容易吃亏的地方：<strong>同一条命令在 A 目录敲和在 B 目录敲，结果可能完全不同</strong>——因为相对路径是&quot;相对当前目录&quot;的。想写&quot;不管在哪儿都指同一个地方&quot;的路径，就用绝对路径（以 <code>/</code> 开头）；<a href="/posts/编程学习/javaweb学习笔记/107-linux常用命令/">107 篇</a>的 <code>find</code> / <code>grep</code> 举例里会出现 <code>find . -name &quot;*.log&quot;</code>，那个 <code>.</code> 也是路径的一种写法，意思是&quot;当前目录&quot;。</p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>后端为什么要学 Linux？</td><td><strong>服务器上跑的就是它</strong>——软件环境（MySQL、Redis、MQ）+ 项目部署（后端 jar、前端静态资源）都在 Linux 上，写代码可以挑系统、部署项目没得挑</td></tr><tr><td>操作系统怎么分类？</td><td>桌面（Windows / Mac OS / Linux）、移动设备（Android / IOS / HarmonyOS）、服务器（Unix / Linux / Windows Server）；<strong>Linux 在服务器里&quot;安全、稳定、免费、占有率高&quot;</strong></td></tr><tr><td>内核版和发行版差在哪？</td><td><strong>内核版</strong>由 Linux 核心团队开发维护、免费开源、负责控制硬件；<strong>发行版</strong>是各厂商在内核之上扩展出来的，有免费也有收费</td></tr><tr><td>6 个发行版？</td><td>Ubuntu（桌面为主，免费）、RedHat（企业，收费）、<strong>CentOS（RedHat 社区版，免费——课程用它）</strong>、Fedora、openSUSE、红旗 Linux</td></tr><tr><td>两种安装方式？</td><td><strong>物理机安装</strong>（直接装到服务器硬件上）和<strong>虚拟机安装</strong>（用虚拟机软件模拟出一台完整计算机）；虚拟机软件：<strong>VMware WorkStation</strong>、VirtualBox、VMLite WorkStation</td></tr><tr><td>装虚拟机的三步？</td><td>① 双击安装 <strong>VMware</strong> ② 解压 CentOS7 镜像包、<strong>双击 <code>.vmx</code></strong> 挂载 ③ <strong>启动服务器</strong>（登录 <code>root</code> / <code>1234</code>）</td></tr><tr><td>网络要怎么配？</td><td>VMware 的&quot;<strong>编辑 → 虚拟网络编辑器</strong>&quot;里选 <strong>VMnet8 的 NAT 模式</strong>，<strong>子网 IP 填 <code>192.168.100.0</code></strong>；配完才能从 Windows 连到 Linux</td></tr><tr><td>怎么查 IP / 没 IP 怎么办？</td><td>坐进虚拟机执行 <strong><code>ip addr</code></strong>，看 <code>ens33</code> 网卡的 <code>inet</code> 地址；<strong>没有 IP 就执行 <code>start-ens33.sh</code> 手动激活 ens33 网卡</strong></td></tr><tr><td>关机、重启的命令？</td><td><strong><code>init 0</code></strong> 关机、<strong><code>init 6</code></strong> 重启（图形界面也能点，但远程连上之后只能靠命令）</td></tr><tr><td>为什么要远程连接？</td><td>服务器在机房（可能在上海、香港、海外），人不可能过去，只能通过网络连它的 <strong>22 端口</strong>操作</td></tr><tr><td>SSH 与工具？</td><td><strong>SSH = Secure Shell，安全外壳协议</strong>；工具：Putty、SecureCRT、Xshell、<strong>FinalShell</strong>（国产免费、带上传下载，课程用它）</td></tr><tr><td>FinalShell 怎么连？</td><td>新建 <strong>SSH 连接</strong>：名称/主机填<strong>虚拟机的 IP</strong>（如 <code>192.168.100.128</code>）、端口 <strong>22</strong>、用户名 <strong><code>root</code></strong>、密码（课程里 <code>1234</code>）——主机就是 IP，端口是 SSH 的默认端口</td></tr><tr><td>Linux 目录的特点？</td><td><strong><code>/</code> 是所有目录的顶点</strong>，结构像<strong>倒挂的树</strong>；Windows 是&quot;多棵（每个盘一棵）树&quot;，Linux <strong>只有一棵</strong></td></tr><tr><td>12 个目录？</td><td><code>bin</code>（二进制可执行文件）、<code>boot</code>（系统引导）、<code>dev</code>（设备文件）、<strong><code>etc</code>（系统配置文件）</strong>、<code>home</code>（用户文件）、<code>lib</code>（共享库）、<code>opt</code>（额外可选应用）、<code>root</code>（超级用户目录）、<code>sbin</code>（二进制可执行文件，只有 root 能访问）、<strong><code>tmp</code>（临时文件）</strong>、<strong><code>usr</code>（系统应用程序，<code>/usr/local</code> 装自己下的软件）</strong>、<strong><code>var</code>（运行时改变的数据，如日志）</strong></td></tr><tr><td>绝对路径与相对路径？</td><td><strong>以 <code>/</code> 开头的是绝对路径</strong>（从根开始找），<strong>不以 <code>/</code> 开头的是相对路径</strong>（从当前目录开始找）：<code>/itheima</code> ≠ <code>itheima</code></td></tr><tr><td>本机实测的环境与结论？</td><td>本机是 <strong>WSL Ubuntu 24.04.3 LTS</strong>（内核 <code>6.6.87.2-microsoft-standard-WSL2</code>），<code>whoami</code> 是 <code>dumplingandcake</code>、<code>which java nginx mysql vim</code> 只有 <code>/usr/bin/vim</code>；<strong>课程环境是 CentOS 7，包管理用 <code>yum</code>、防火墙用 <code>firewalld</code>，别把 Ubuntu 的 <code>apt</code> 抄进去</strong></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/javaweb学习笔记/105-前端打包部署/">上一篇：前端打包部署</a></li><li><a href="/posts/编程学习/javaweb学习笔记/107-linux常用命令/">下一篇：Linux常用命令</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li><strong>为什么后端要学 Linux</strong>：服务器上跑的就是 Linux——**软件环境（MySQL、Redis、MQ）+ 项目部署（后端 jar、前端静态资源）**都在这上面；写代码可以挑系统，部署项目没得挑</li><li><strong>操作系统分类</strong>：桌面（Windows / Mac OS / Linux）、移动设备（Android / IOS / HarmonyOS）、服务器（Unix / Linux / Windows Server）；Linux 在服务器场景里是&quot;<strong>安全、稳定、免费、占有率高</strong>&quot;</li><li><strong>内核版 vs 发行版</strong>：内核版由 <strong>Linux 核心团队</strong>开发维护、免费开源、<strong>负责控制硬件</strong>；发行版基于内核版扩展、由<strong>各 Linux 厂商</strong>开发维护，有收费也有免费。常见发行版 6 个——Ubuntu（桌面应用为主，免费）、RedHat（面向企业，收费）、<strong>CentOS（RedHat 的社区版，免费——课程用它）</strong>、Fedora（功能完备、快速更新）、openSUSE（对个人免费、界面华丽）、红旗 Linux</li><li><strong>两种安装方式</strong>：<strong>物理机安装</strong>（直接把操作系统装到服务器硬件上）和<strong>虚拟机安装</strong>（通过虚拟机软件安装）。<strong>虚拟机</strong>指通过软件模拟的具有完整硬件系统功能、运行在完全隔离环境中的完整计算机系统；三款软件是 <strong>VMWare WorkStation / VirtualBox / VMLite WorkStation</strong></li><li><strong>装虚拟机三步</strong>：① 双击运行 <strong>VMware</strong> 安装程序；② 解压 CentOS7 镜像包到磁盘目录、<strong>双击 <code>.vmx</code> 文件</strong>完成挂载；③ <strong>启动服务器</strong>，登录 <strong>root / 1234</strong></li><li><strong>网络配置</strong>：VMware 菜单&quot;编辑 → <strong>虚拟网络编辑器</strong>&quot;→ 选 <strong>VMnet8 的 NAT 模式</strong> → <strong>子网 IP 设为 <code>192.168.100.0</code></strong>；配完才能在 Windows 上连虚拟机里的 Linux</li><li><strong>查 IP 与激活网卡</strong>：<strong><code>ip addr</code></strong> 查看 IP 地址；<strong>没有 IP 就执行 <code>start-ens33.sh</code></strong> 手动激活 <strong>ens33</strong> 网卡。另外 <strong><code>init 0</code> 关机、<code>init 6</code> 重启</strong></li><li><strong>远程连接</strong>：服务器在机房（可能在上海/天津/香港/海外），人过不去，只能通过网络连它。<strong>SSH = Secure Shell，安全外壳协议</strong>；常用工具 <strong>Putty、SecureCRT、Xshell、FinalShell</strong>；FinalShell 的连接要填 <strong>主机（虚拟机 IP）、端口 22、用户名 root、密码</strong></li><li><strong>目录结构与路径</strong>：<strong><code>/</code> 是所有目录的顶点</strong>，结构像<strong>倒挂的树</strong>（Windows 是多棵树）；12 个目录见上表（重点：<code>etc</code> 配置文件、<code>usr</code> 系统应用程序/<code>/usr/local</code>、<code>var</code> 日志、<code>tmp</code> 临时、<code>root</code> 超级用户目录、<code>sbin</code> 只有 root 能访问）；<strong>以 <code>/</code> 开头是绝对路径，不以 <code>/</code> 开头是相对路径</strong></li><li><strong>本机的实测环境</strong>：<strong>WSL Ubuntu 24.04.3 LTS</strong>（内核 <code>6.6.87.2-microsoft-standard-WSL2</code>），<code>whoami</code> = <code>dumplingandcake</code>，<code>which java nginx mysql vim</code> 只回显 <code>/usr/bin/vim</code>（说明这台机器上 JDK/MySQL/Nginx 都没装，正好对应本章后面的软件安装）；<strong>课程环境是 CentOS 7（<code>yum</code> / <code>firewalld</code>），本机是 Ubuntu（<code>apt</code> / <code>ufw</code>），命令别混</strong></li></ol><h3 id="二、裸写题" tabindex="-1">二、裸写题 <a class="header-anchor" href="#二、裸写题" aria-label="Permalink to &quot;二、裸写题&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 先认清这个系统：它属于哪一类、又是哪个版本</strong> 需求：两问一起做。<strong>第一问（分类）</strong>：判断下面三句话分别在说哪个场景的操作系统，并各补一个&quot;这个场景里的代表系统 + 它最突出的特点&quot;：① &quot;用户数量最多，办公和家庭最常见&quot;；② &quot;基于 Linux、开源，主要用在智能手机、平板、智能电视&quot;；③ &quot;安全、稳定、免费、占有率高&quot;；再说出第③句里的那个系统&quot;<strong>我们为什么要专门学它</strong>&quot;的两条理由。<strong>第二问（版本）</strong>：用一张两列表把&quot;<strong>内核版</strong>&quot;和&quot;<strong>发行版</strong>&quot;比清楚——谁开发维护、收不收费、各自负责干什么；然后回答：① 课程为什么选 CentOS？② Ubuntu 属于哪一类？③ &quot;由厂商开发维护、基于内核版进行扩展&quot;说的是哪一个？ 素材：PPT 第 4 页那张三行九列的分类表；PPT 第 7 页的六款发行版（Ubuntu、RedHat、CentOS、Fedora、openSUSE、红旗 Linux）。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：第一问先把&quot;桌面 / 移动设备 / 服务器&quot;三行认出来，再想后端工程师真正要打交道的是哪一行；第二问想想&quot;发动机与整车&quot;的关系——只有一套发动机（核心团队维护），但各家厂商拿它造出不同的车（发行版） <strong>二级 · 方法</strong>：第一问——桌面行写 <strong>Windows / Mac OS / Linux</strong>，移动设备行 <strong>Android / IOS / HarmonyOS</strong>，服务器行 <strong>Unix / Linux / Windows Server</strong>；&quot;为什么要学&quot;的两条理由是<strong>服务器上跑的就是它</strong>：软件环境（mysql、redis、MQ）+ 项目部署。第二问——内核版 = <strong>Linux 核心团队</strong>开发维护、<strong>免费开源</strong>、<strong>负责控制硬件</strong>；发行版 = 基于内核版扩展、<strong>各 Linux 厂商</strong>开发维护、<strong>有收费也有免费</strong>；CentOS 是 <strong>RedHat 的社区版、免费</strong>，所以课程用它 <strong>三级 · 骨架</strong>：分类：① 桌面 <code>____</code> ② 移动设备 <code>____</code> ③ 服务器 <code>____</code> ＋ 理由 <code>____</code>、<code>____</code>；版本：内核版（维护 <code>____</code>、费用 <code>____</code>、职责 <code>____</code>）/ 发行版（维护 <code>____</code>、费用 <code>____</code>）</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【第一问：操作系统分类】</span></span>
<span class="line"><span>① 桌面操作系统 —— Windows（用户数量最多）；同场景还有 Mac OS（操作体验好、</span></span>
<span class="line"><span>   办公人士首选）、Linux（用户数量少）。</span></span>
<span class="line"><span>② 移动设备操作系统 —— Android（基于 Linux、开源，主要用于智能手机、平板、</span></span>
<span class="line"><span>   智能电视）；同场景还有 IOS（苹果开发、不开源）、HarmonyOS（华为开发、开源）。</span></span>
<span class="line"><span>③ 服务器操作系统 —— Linux（安全、稳定、免费、占有率高）；同场景还有</span></span>
<span class="line"><span>   Unix（安全、稳定、付费）、Windows Server（付费、占有率低）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   为什么要专门学 Linux（PPT 第 4 页右下角那两行）：</span></span>
<span class="line"><span>     · 软件环境：MySQL、Redis、MQ 这些中间件都装在 Linux 服务器上、在它上面跑；</span></span>
<span class="line"><span>     · 项目部署：后端 SpringBoot 工程打的 jar、前端打包出来的静态资源，</span></span>
<span class="line"><span>       最终都部署到 Linux 服务器上。</span></span>
<span class="line"><span>   一句话：写代码可以挑系统，部署项目没得挑。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【第二问：内核版与发行版】</span></span>
<span class="line"><span>               内核版（Kernel）            发行版（Distribution）</span></span>
<span class="line"><span>谁开发维护  Linux 核心团队             各个 Linux 厂商</span></span>
<span class="line"><span>收不收费    免费、开源                 有收费版本也有免费版本</span></span>
<span class="line"><span>干什么      负责控制硬件               基于 Linux 内核版进行扩展</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① 课程选 CentOS 因为它是 RedHat 的社区版：</span></span>
<span class="line"><span>   · 和收费的企业版 RedHat 同源（企业里真在用它）；</span></span>
<span class="line"><span>   · 自己免费，拿来教学不用花钱。</span></span>
<span class="line"><span>② Ubuntu 属于发行版（以桌面应用为主，免费）。</span></span>
<span class="line"><span>③ &quot;由厂商开发维护、基于内核版扩展&quot;说的是发行版。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   顺便记一下课程环境与实测环境的差别：</span></span>
<span class="line"><span>     课程用的是 CentOS 7 —— 包管理 yum、防火墙 firewalld；</span></span>
<span class="line"><span>     本机实测环境是 Ubuntu 24.04 —— 包管理 apt、防火墙 ufw。</span></span>
<span class="line"><span>     命令（ls/cd/cp/tar/find/grep…）两边一样，包管理与防火墙命令别混。</span></span></code></pre></div><p>检查点：① 三行的系统别串行（Android 属于移动设备、Linux 属于服务器）；② 能说清&quot;服务器上跑的就是 Linux&quot;；③ 内核版是&quot;核心团队 + 控制硬件&quot;、发行版是&quot;厂商 + 扩展&quot;，并知道 CentOS = RedHat 社区版、免费；④ 能说出 CentOS 与 Ubuntu 至少两处命令差异（<code>yum</code> vs <code>apt</code>、<code>firewalld</code> vs <code>ufw</code>）。</p></details></li><li><p>[ ] <strong>2-2 在一台 Windows 电脑上把 CentOS 7 跑起来</strong> 需求：手上只有一台装着 Windows 的电脑，也拿到了老师给的 CentOS7 虚拟机文件（一个压缩包）。请写出**从&quot;什么都没有&quot;到&quot;看到一个能登录的 Linux&quot;**的完整步骤：① 装什么软件；② 压缩包怎么用；③ 哪个文件是&quot;入口&quot;、怎么把它挂进去；④ 开机之后用什么账号密码登录；⑤ 顺手说出虚拟机的定义（用 PPT 的原话）和&quot;为什么学习阶段宁愿用虚拟机也不用物理机&quot;的两条理由。 素材：PPT 第 8、9、11 页；虚拟机软件三款 VMWare WorkStation / VirtualBox / VMLite WorkStation；登录账号 <code>root</code>、密码 <code>1234</code>。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：三件事——<strong>先有&quot;能跑虚拟机的软件&quot;</strong>、<strong>再把机器文件挂进去</strong>、<strong>最后开机登录</strong>。第二步的入口不是 <code>.vmdk</code>（那是虚拟硬盘），而是图标带 VMware 标志的那个文件 <strong>二级 · 方法</strong>：装 <strong>VMware WorkStation</strong>（双击安装程序一路下一步）；把 CentOS7 镜像压缩包<strong>解压到磁盘目录</strong>，里面的 <strong><code>.vmx</code></strong> 文件就是入口——<strong>双击它</strong>（选 VMware Workstation 打开、勾&quot;始终使用此应用&quot;）完成<strong>挂载</strong>；然后在 VMware 里点&quot;<strong>开启此虚拟机</strong>&quot;，用 <strong>root / 1234</strong> 登录。虚拟机定义：通过软件模拟的具有完整硬件系统功能、运行在完全隔离环境中的完整计算机系统 <strong>三级 · 骨架</strong>：① 装 <code>____</code>；② 解压镜像包到 <code>____</code>；③ 双击 <code>____</code> 完成挂载；④ 点 <code>____</code>，用 <code>____</code> / <code>____</code> 登录；⑤ 定义：用软件模拟的 <code>____</code>、运行在 <code>____</code> 环境中的完整计算机系统；理由：<code>____</code>、<code>____</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 装虚拟机软件：VMware WorkStation（双击安装程序，按提示完成安装即可）</span></span>
<span class="line"><span>   —— 课程资料里给的就是它；另两款是 VirtualBox、VMLite WorkStation。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 解压 CentOS7 的镜像压缩包到磁盘目录（比如 D:\\VMimages\\CentOS7-1），</span></span>
<span class="line"><span>   解压出来是一堆文件：CentOS 7 64 位.vmx、.vmdk（虚拟硬盘，可能有 s001~s013）、</span></span>
<span class="line"><span>   .nvram、.vmsd …</span></span>
<span class="line"><span>   注意：这一堆文件不能单独删、不能单独移动，要动就整个文件夹一起动。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 入口是 CentOS 7 64 位.vmx，双击它 → 弹出&quot;你要如何打开这个文件?&quot;→</span></span>
<span class="line"><span>   选 VMware Workstation（勾&quot;始终使用此应用打开 .vmx 文件&quot;）→ 完成挂载，</span></span>
<span class="line"><span>   这台机器就出现在 VMware 的列表里了。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ 在 VMware 里点&quot;开启此虚拟机&quot;启动；登录账号 root，密码 1234。</span></span>
<span class="line"><span>   root 是 Linux 的超级管理员（相当于 Windows 的 Administrator）；</span></span>
<span class="line"><span>   后面装软件、部署项目都用这个账号。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>⑤ 虚拟机的定义（PPT 第 8 页原话）：</span></span>
<span class="line"><span>   指通过软件模拟的具有完整硬件系统功能、运行在完全隔离环境中的完整计算机系统。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   学习阶段用虚拟机（而不是物理机）的两条理由：</span></span>
<span class="line"><span>   · 不破坏本机：装系统、删软件、改配置随便折腾，坏了删掉重来；</span></span>
<span class="line"><span>   · 可以随时回到过去：支持快照，装完干净的 CentOS 7 先拍一张，之后能回滚；</span></span>
<span class="line"><span>   （第三条：本机 Windows 要留着开发——IDEA、Node、浏览器都在上面。）</span></span></code></pre></div><p>检查点：① 顺序是&quot;装 VMware → 解压 → 双击 .vmx → 开启虚拟机&quot;；② 入口写的是 <strong><code>.vmx</code></strong> 而不是 <code>.vmdk</code>；③ 登录写 <strong>root / 1234</strong>；④ 虚拟机定义能说出&quot;软件模拟 + 完整硬件功能 + 完全隔离环境&quot;；⑤ 理由里至少有&quot;不破坏本机 / 可快照回滚&quot;中的一条。</p></details></li><li><p>[ ] <strong>2-3 配好网络、查到 IP、远程连上去</strong> 需求：CentOS 7 的虚拟机已经装好了，现在要从 Windows 上用 FinalShell 连过去，但直接连是连不上的。请按顺序写出全过程：① 在 VMware 里把网络配成什么样（菜单怎么走、选哪个模式、子网 IP 填什么）；② 进虚拟机用什么命令查 IP、网卡名是什么、<strong>如果没查到 IP 该怎么办</strong>；③ 在 FinalShell 里新建连接时&quot;名称/主机/端口/用户名/密码&quot;分别填什么；④ 最后说出在 FinalShell 里敲命令和在虚拟机里敲命令有没有区别，为什么。 素材：PPT 第 10、12、17 页；虚拟机里查到的 IP 是 <code>192.168.100.128</code>；SSH 默认端口 22；登录用户 root。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：四步是&quot;<strong>在 VMware 里给虚拟机配一张网卡</strong> → <strong>在 Linux 里确认这张网卡拿到了地址</strong> → <strong>在 Windows 上让 FinalShell 拿着这个地址连过去</strong> → <strong>连上之后就是黑窗口敲命令</strong>&quot; <strong>二级 · 方法</strong>：菜单&quot;<strong>编辑 → 虚拟网络编辑器</strong>&quot;→ 选 <strong>VMnet8 的 NAT 模式</strong> → 子网 IP 填 <strong><code>192.168.100.0</code></strong>；进虚拟机执行 <strong><code>ip addr</code></strong> 看网卡 <strong>ens33</strong> 的 <code>inet</code> 地址，<strong>没有 IP 就执行 <code>start-ens33.sh</code></strong> 手动激活 ens33 网卡；FinalShell 新建 <strong>SSH 连接</strong>，主机填 IP、端口 <strong>22</strong>、用户名 <strong>root</strong>、密码（<code>1234</code>）；连上后敲命令没有区别，因为<strong>远程连接就是开了一个到服务器的终端</strong>，命令是由对面那台 Linux 执行的 <strong>三级 · 骨架</strong>：① <code>____</code> → <code>____</code> → 子网 IP <code>____</code>；② <code>____</code> 看 <code>____</code> 网卡，没 IP 就 <code>____</code>；③ 主机 <code>____</code>、端口 <code>____</code>、用户名 <code>____</code>；④ 没区别，因为命令在 <code>____</code> 上执行</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 配置虚拟网卡（VMware 里）：</span></span>
<span class="line"><span>   VMware 菜单栏「编辑(E) → 虚拟网络编辑器(N)...」→ 选中 VMnet8 →</span></span>
<span class="line"><span>   模式选「NAT 模式（用于共享主机的 IP 地址）」→</span></span>
<span class="line"><span>   子网 IP (I) 填 192.168.100.0，子网掩码 255.255.255.0 → 应用 / 确定。</span></span>
<span class="line"><span>   （为什么用 NAT：虚拟机通过主机上网、主机能访问虚拟机，外面看不进来；</span></span>
<span class="line"><span>     192.168.100.0 是私有网段，课程统一用这个，截图里的 IP 也都是这个网段。）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 查 IP（在虚拟机的终端里执行）：</span></span>
<span class="line"><span>   ip addr</span></span>
<span class="line"><span>   看 ens33 这块网卡下面的 inet 地址（比如 192.168.100.128）。</span></span>
<span class="line"><span>   如果 ens33 下没有 inet 地址（没查到 IP）：</span></span>
<span class="line"><span>       ./start-ens33.sh        # 手动激活 ens33 网卡，然后再 ip addr 确认一次</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ FinalShell（Windows 上）新建连接：</span></span>
<span class="line"><span>   左侧选「SSH 连接」；</span></span>
<span class="line"><span>   常规 → 名称：192.168.100.128（和主机一致即可）</span></span>
<span class="line"><span>          主机：192.168.100.128     ← 填虚拟机的 IP</span></span>
<span class="line"><span>          端口：22                  ← SSH 的默认端口</span></span>
<span class="line"><span>   认证 → 方法：密码</span></span>
<span class="line"><span>          用户名：root</span></span>
<span class="line"><span>          密码：（课程里是 1234）</span></span>
<span class="line"><span>   确定后双击列表里的连接即可。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ 在 FinalShell 里敲命令和坐在虚拟机前敲命令没有区别：</span></span>
<span class="line"><span>   远程连接只是把虚拟机的一个终端&quot;搬&quot;到了你的 Windows 上，</span></span>
<span class="line"><span>   命令真正执行的地方还是那台 Linux（所以目录、文件、权限全都是它的）。</span></span></code></pre></div><p>检查点：① 选的是 <strong>NAT 模式</strong>、子网 IP 是 <strong><code>192.168.100.0</code></strong>（不是随便一个网段）；② 查 IP 用 <strong><code>ip addr</code></strong>、没 IP 用 <strong><code>start-ens33.sh</code></strong> 激活 <strong>ens33</strong>；③ 端口写 <strong>22</strong>、用户名 <strong>root</strong>、主机填 <strong>虚拟机的 IP</strong>；④ 能解释&quot;远程连的其实是同一台机器&quot;。</p></details></li><li><p>[ ] <strong>2-4 一个路径到底是绝对路径还是相对路径</strong> 需求：判断下面四条路径分别是绝对路径还是相对路径，并说出它到底指向哪里（假设当前用户在 <code>/home/dumplingandcake</code>）：① <code>/usr/local</code>；② <code>itcast</code>；③ <code>/etc/profile</code>；④ <code>../itheima</code>。再回答两个附加问题：Linux 的目录结构和 Windows 有什么根本区别（谁是多棵树、谁是倒挂的树）？下面这些&quot;东西&quot;该放在哪个目录——<strong>系统配置文件</strong>、<strong>自己下载安装的软件</strong>、<strong>日志文件</strong>、<strong>临时试验文件</strong>、<strong>root 用户的家目录</strong>？ 素材：PPT 第 19、20、21 页；12 个目录表。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：只看一件事——<strong>开头有没有 <code>/</code></strong>。有就是从根开始找（绝对），没有就是从当前目录开始找（相对）。至于&quot;该放哪&quot;，靠的是每个目录的职责分工 <strong>二级 · 方法</strong>：<code>/usr/local</code>、<code>/etc/profile</code> 以 <code>/</code> 开头是<strong>绝对路径</strong>；<code>itcast</code> 不以 <code>/</code> 开头是<strong>相对路径</strong>（= 当前目录下的 itcast）；<code>../itheima</code> 也是相对路径（<code>..</code> 是上一级目录）。放东西：配置文件 → <strong><code>etc</code></strong>，自己装的软件 → <strong><code>/usr/local</code></strong>（<code>usr</code> 是系统应用程序目录），日志 → <strong><code>var</code></strong>（运行时改变的数据），临时文件 → <strong><code>tmp</code></strong>，root 的家目录 → <strong><code>/root</code></strong><strong>三级 · 骨架</strong>：① 绝对，指向 <code>____</code>；② 相对，指向 <code>____</code>；③ 绝对，指向 <code>____</code>；④ 相对，指向 <code>____</code> 的上一级目录里的 <code>____</code>；Linux 只有 <code>____</code> 棵树、顶点是 <code>____</code>，Windows 是 <code>____</code> 棵树；落点：配置 <code>____</code> / 软件 <code>____</code> / 日志 <code>____</code> / 临时 <code>____</code> / root 家目录 <code>____</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>四条路径（当前在 /home/dumplingandcake）：</span></span>
<span class="line"><span>① /usr/local      → 绝对路径（以 / 开头，从根目录开始找）：根下 usr 里的 local 目录</span></span>
<span class="line"><span>② itcast          → 相对路径：当前目录下的 itcast，也就是</span></span>
<span class="line"><span>                    /home/dumplingandcake/itcast</span></span>
<span class="line"><span>③ /etc/profile    → 绝对路径：根下 etc 里的 profile 文件（系统配置文件）</span></span>
<span class="line"><span>④ ../itheima      → 相对路径：当前目录的上一级目录里的 itheima，也就是</span></span>
<span class="line"><span>                    /home/itheima（.. 表示上一级目录）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目录结构的根本区别：</span></span>
<span class="line"><span>  · Linux 只有一棵树，/ 是所有目录的顶点，结构像一颗倒挂的树；</span></span>
<span class="line"><span>  · Windows 是多棵树，每个盘符（C:、D:、E:）各是一棵树，盘符就是&quot;根&quot;。</span></span>
<span class="line"><span>  · 在 Linux 里，&quot;盘&quot;是被挂到树上某个目录里的，不会在根上多长出一棵树。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>东西该放哪：</span></span>
<span class="line"><span>  系统配置文件      → /etc        （比如 /etc/profile 配环境变量）</span></span>
<span class="line"><span>  自己下载安装的软件 → /usr/local  （usr 是系统应用程序目录，local 是&quot;后来自己装的&quot;）</span></span>
<span class="line"><span>  日志文件          → /var        （存放运行时需要改变数据的文件，例如日志）</span></span>
<span class="line"><span>  临时试验文件      → /tmp        （存放临时文件）</span></span>
<span class="line"><span>  root 用户的家目录  → /root       （超级用户目录，就在根下，不在 /home 里）</span></span></code></pre></div><p>检查点：① 判断标准只有&quot;开头有没有 <code>/</code>&quot;；② 相对路径要说出&quot;相对于当前目录&quot;的结果；③ 能说出&quot;Linux 一棵树 / Windows 多棵树&quot;；④ 五个落点全对（尤其 <code>/usr/local</code> 和 <code>/var</code>）。</p></details></li></ul><h3 id="三、综合题" tabindex="-1">三、综合题 <a class="header-anchor" href="#三、综合题" aria-label="Permalink to &quot;三、综合题&quot;">​</a></h3><ul><li><p>[ ] <strong>3-1 写一份&quot;从一台 Windows 电脑到远程操作 CentOS 7&quot;的清单</strong> 需求：假设你现在什么都没装，只有一台 Windows 电脑和老师给的资料包（里面有 VMware 安装程序、CentOS7 镜像压缩包、FinalShell 安装程序）。请写出一份<strong>可以照着做的清单</strong>，把下面每一站都写清&quot;做什么、得到什么结果、怎么确认成功&quot;：</p><ol><li><strong>认清环境</strong>：这一章为什么必须学 Linux（写两条理由）</li><li><strong>装虚拟机软件</strong>：装哪个软件、怎么装</li><li><strong>挂载并启动 CentOS 7</strong>：压缩包怎么处理、哪个文件是入口、怎么开机、用什么账号登录</li><li><strong>配网络</strong>：在 VMware 里改哪一项（模式 + 子网 IP 写成什么），为什么必须是这个网段</li><li><strong>在 Linux 里确认 IP</strong>：用什么命令看哪个网卡，如果没看到 IP 怎么办</li><li><strong>从 Windows 远程连上去</strong>：用什么工具、连接里四项信息分别填什么、怎么判断连上了</li><li><strong>收尾一层</strong>：连上之后，你打算把&quot;自己下载的软件&quot;和&quot;临时试验文件&quot;分别放在哪个目录？为什么（各说一句职责）？</li><li><strong>自查</strong>：把清单和 PPT 第 12、17 页对一遍，看有没有漏项</li></ol><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：整条链路是<strong>本机（Windows）→ VMware 软件 → 虚拟机（CentOS 7）→ 网络（同一 NAT 网段）→ 远程客户端（FinalShell）</strong>；每一站都问自己&quot;东西在哪儿、怎么确认它在正常工作&quot; <strong>二级 · 方法</strong>：VMware 双击安装；CentOS7 压缩包解压后<strong>双击 <code>.vmx</code></strong> 挂载、<strong>开启此虚拟机</strong>、<code>root</code>/<code>1234</code> 登录；虚拟网络编辑器里 <strong>VMnet8 + NAT 模式 + 子网 IP 192.168.100.0</strong>；<code>ip addr</code> 看 <strong>ens33</strong>，没 IP 就 <code>start-ens33.sh</code>；FinalShell 新建 <strong>SSH 连接</strong>（主机 = 虚拟机 IP、端口 <strong>22</strong>、用户名 <strong>root</strong>、密码 <code>1234</code>）；自己装的软件放 <strong><code>/usr/local</code></strong>，临时的放 <strong><code>/tmp</code></strong><strong>三级 · 骨架</strong>：清单七段——① 理由（<code>____</code>、<code>____</code>）② 装 <code>____</code> ③ 双击 <code>____</code> 挂载 + 开启 + 登录 <code>____</code>/<code>____</code> ④ <code>____</code> 模式 + 子网 IP <code>____</code> ⑤ <code>____</code> 看 <code>____</code>（没有就 <code>____</code>）⑥ 工具 <code>____</code>：主机 <code>____</code>、端口 <code>____</code>、用户 <code>____</code> ⑦ 软件 <code>____</code>、临时 <code>____</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>清单：从一台 Windows 电脑到远程操作 CentOS 7</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【1】认清环境——为什么必须学 Linux</span></span>
<span class="line"><span>  · 服务器上跑的就是 Linux：软件环境（MySQL、Redis、MQ）都装在上面；</span></span>
<span class="line"><span>  · 项目部署：后端 jar、前端打包出来的静态资源最终都部署到 Linux 服务器。</span></span>
<span class="line"><span>  · 一句话：写代码可以挑系统，部署项目没得挑。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【2】装虚拟机软件（PPT 第 9 页）</span></span>
<span class="line"><span>  · 装的是 VMware WorkStation：双击资料里的安装程序 → 接受许可 → 选安装目录</span></span>
<span class="line"><span>    （想省 C 盘空间就换盘）→ 一路下一步，完成后重启。</span></span>
<span class="line"><span>  · 确认成功：开始菜单/桌面能找到 VMware Workstation，打开能看到&quot;库&quot;的界面。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【3】挂载并启动 CentOS 7（PPT 第 11 页）</span></span>
<span class="line"><span>  · 解压 CentOS7 镜像压缩包到磁盘目录（如 D:\\VMimages\\CentOS7-1）；</span></span>
<span class="line"><span>  · 目录里的 CentOS 7 64 位.vmx 是入口文件，双击它 →（选 VMware Workstation</span></span>
<span class="line"><span>    打开、勾&quot;始终使用此应用&quot;）→ 完成挂载；</span></span>
<span class="line"><span>  · 在 VMware 里点「开启此虚拟机」，启动后登录：账号 root，密码 1234。</span></span>
<span class="line"><span>  · 确认成功：屏幕上是 CentOS 7 的登录界面/桌面，能进去。</span></span>
<span class="line"><span>  · 注意：那一堆 .vmx/.vmdk 文件不能单独删、单独移动，要动整个文件夹一起动。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【4】配置网络（PPT 第 10、12 页）</span></span>
<span class="line"><span>  · 位置：VMware 菜单「编辑 → 虚拟网络编辑器」；</span></span>
<span class="line"><span>  · 选中 VMnet8 → 模式勾「NAT 模式」→ 子网 IP 填 192.168.100.0</span></span>
<span class="line"><span>    （子网掩码 255.255.255.0）→ 应用 / 确定。</span></span>
<span class="line"><span>  · 为什么必须是 NAT + 192.168.100.0：</span></span>
<span class="line"><span>    NAT = 虚拟机通过主机上网、主机能访问虚拟机，外面看不进来，换网络也不用重配；</span></span>
<span class="line"><span>    192.168.100.0 是私有网段，课程统一用它，所有演示和截图里的 IP 都是这个网段。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【5】在 Linux 里确认 IP（PPT 第 12 页）</span></span>
<span class="line"><span>  · 命令：ip addr    → 看 ens33 网卡下的 inet 地址（如 192.168.100.128）；</span></span>
<span class="line"><span>  · 如果没有 IP：执行 ./start-ens33.sh 手动激活 ens33 网卡，再 ip addr 复查；</span></span>
<span class="line"><span>  · 顺带记：init 0 关机、init 6 重启。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【6】远程连上去（PPT 第 15～17 页）</span></span>
<span class="line"><span>  · 工具：FinalShell（SSH 协议，默认端口 22）；</span></span>
<span class="line"><span>  · 新建「SSH 连接」：主机 = 虚拟机 IP（192.168.100.128）、端口 22、</span></span>
<span class="line"><span>    用户名 root、密码 1234；名称可以和主机写成一样，方便认；</span></span>
<span class="line"><span>  · 确认成功：连接列表里双击后出现一个远程终端，能敲命令且提示符显示</span></span>
<span class="line"><span>    [root@localhost ~]# 之类的信息（连不上先查：虚拟机 IP、VMnet8 这张</span></span>
<span class="line"><span>    虚拟网卡在不在、虚拟机开没开机）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【7】收尾——东西放哪</span></span>
<span class="line"><span>  · 自己下载安装的软件 → /usr/local（usr 是系统应用程序目录，</span></span>
<span class="line"><span>    local 是&quot;后来自己装的&quot;地方；后面 JDK、MySQL、Nginx 都装这儿）；</span></span>
<span class="line"><span>  · 临时试验文件 → /tmp（存放临时文件）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【8】自查（对 PPT 第 12、17 页）</span></span>
<span class="line"><span>  网络：NAT 模式 + 子网 IP 192.168.100.0 + ip addr + start-ens33.sh + init 0/6 ✔</span></span>
<span class="line"><span>  远程：SSH + FinalShell + 主机/22/root/密码 ✔</span></span>
<span class="line"><span>  目录：/usr/local 放自己装的软件、/tmp 放临时文件 ✔</span></span></code></pre></div><p>检查点：① 清单每一步都写了&quot;在哪儿做、怎么确认&quot;；② 网络那一步写的是 VMware 的<strong>虚拟网络编辑器 + NAT + 192.168.100.0</strong>（不是去 Linux 里改文件）；③ 登录信息（<code>root</code>/<code>1234</code>）和连接信息（端口 <code>22</code>）没写错；④ 知道没有 IP 时用 <code>start-ens33.sh</code>；⑤ 目录落点写对（<code>/usr/local</code>、<code>/tmp</code>）。</p></details></li></ul>`,138)])])}const h=s(e,[["render",d]]);export{u as __pageData,h as default};
